const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const jakarta = ee.Geometry.Point([106.8, -6.2]);
  const region = jakarta.buffer(15000); // 15km radius for analysis

  // 2. Cloud masking function
  function maskL5sr(image) {
    const qaMask = image.select('QA_PIXEL').bitwiseAnd(parseInt('11111', 2)).eq(0);
    const saturationMask = image.select('QA_RADSAT').eq(0);
    return image.updateMask(qaMask).updateMask(saturationMask)
      .multiply(0.0000275).add(-0.2);
  }

  // 3. Data Acquisition for 1989
  let col1989 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(region)
    .filterDate('1989-01-01', '1989-12-31')
    .map(maskL5sr);

  const size1989 = await col1989.size().getInfo();
  console.log(`1989 Images: ${size1989}`);

  if (size1989 === 0) {
    console.log("No data for 1989.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Data Acquisition for 2004
  let col2004 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(region)
    .filterDate('2004-01-01', '2004-12-31')
    .map(maskL5sr);

  const size2004 = await col2004.size().getInfo();
  console.log(`2004 Images: ${size2004}`);

  if (size2004 === 0) {
    console.log("No data for 2004.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 5. Create median composites
  const img1989 = col1989.median();
  const img2004 = col2004.median();

  // 6. Calculate NDBI (Built-up index): (SWIR1 - NIR) / (SWIR1 + NIR)
  const ndbi1989 = img1989.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDBI');
  const ndbi2004 = img2004.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDBI');

  // 7. Threshold for urban areas (NDBI > 0)
  const urban1989 = ndbi1989.gt(0);
  const urban2004 = ndbi2004.gt(0);

  // 8. Check pixel counts
  const count1989 = await urban1989.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDBI').getInfo();

  if (count1989 === 0 || count1989 === null) {
    console.log("No valid pixels for 1989 after masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  const count2004 = await urban2004.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDBI').getInfo();

  if (count2004 === 0 || count2004 === null) {
    console.log("No valid pixels for 2004 after masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 9. Calculate urban area (sum of urban pixels * pixel area)
  const urbanArea1989 = await urban1989.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDBI').getInfo();

  const urbanArea2004 = await urban2004.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 3000,
    maxPixels: 1e9
  }).get('NDBI').getInfo();

  // 10. Validation
  if (urbanArea1989 === null || urbanArea2004 === null) {
    console.log("Calculation failed (null result).");
    console.log("<answer>C3</answer>");
    return;
  }

  console.log(`1989 Urban pixels: ${urbanArea1989.toFixed(0)}, Valid count: ${count1989}`);
  console.log(`2004 Urban pixels: ${urbanArea2004.toFixed(0)}, Valid count: ${count2004}`);

  const increase = urbanArea2004 > urbanArea1989;
  const percentChange = ((urbanArea2004 - urbanArea1989) / urbanArea1989 * 100).toFixed(1);
  console.log(`Change: ${percentChange}%`);

  if (increase) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
